"""Writes evaluation results as LaTeX macros for the paper."""

import json
import re

HEADER = """\
% SPDX-FileCopyrightText: 2026 Sascha Brawer <sascha@brawer.ch>
% SPDX-License-Identifier: CC-BY-4.0
%
% Generated by eval/ (make -C eval). Do not edit by hand.
"""


def _name(key):
    # LaTeX macro names take letters only.
    parts = re.split(r"[^A-Za-z]+", key)
    return "res" + "".join(p[:1].upper() + p[1:] for p in parts if p)


def _format(v):
    if isinstance(v, float):
        return f"{v:.3f}" if abs(v) < 1 else f"{v:,.1f}".replace(",", "{,}")
    if isinstance(v, int):
        return f"{v:,}".replace(",", "{,}")
    return str(v)


def _flatten(tree, prefix=""):
    """Yields (key path, value) for the leaves of nested dicts, sorted."""
    for key in sorted(tree):
        value = tree[key]
        path = f"{prefix} {key}".strip()
        if isinstance(value, dict):
            yield from _flatten(value, path)
        else:
            yield path, value


def write(results, tex_path, json_path):
    with open(json_path, "w") as f:
        json.dump(results, f, indent=2, sort_keys=True)
        f.write("\n")
    lines = [HEADER]
    for key, value in _flatten(results):
        lines.append(f"\\newcommand{{\\{_name(key)}}}{{{_format(value)}}}\n")
    with open(tex_path, "w") as f:
        f.writelines(lines)
